def compute(vars):
    previous_value = vars["v1"]
    current_value = vars["v2"]

    if previous_value == 0:
        return None

    change = current_value - previous_value
    change_ratio = change / previous_value
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "previous_value": previous_value,
            "current_value": current_value,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "percent"
            }
        }
    }
